// @pit: {"label": "Write the job summary only when no comment carries the footer"}
async ({ workspace: { read, edit } }) => {
  const r = await read("src/run.ts", { format: "raw" });
  const old = `/** After the final push: where the thread is now, in the log, and how to read it, in the job summary. */`;
  const oldBody = `	try {
		await deps.summary?.(formatThreadSummary(ref, remote));`;
  if (!r.content.includes(old) || !r.content.includes(oldBody)) return "not found";
  const c = r.content
    .replace(old, `/**
 * After the final push: where the thread is now, in the log. How to read it goes in the job summary in \`output\` mode;
 * in \`comment\` mode, each comment has it, collapsed (#80).
 */`)
    .replace(oldBody, `	if (deps.inputs.outputMode !== "output") {
		return;
	}
	try {
		await deps.summary?.(formatThreadSummary(ref, remote));`);
  await edit("src/run.ts", { revision: r.revision, changes: [{ kind: "replaceFile", content: c }] });
  return "ok";
}

